import{_ as a,o as s,c as t,ag as i}from"./chunks/framework.DaCm-iTo.js";const _=JSON.parse('{"title":"CoreLib 动作","description":"","frontmatter":{},"headers":[],"relativePath":"modules/forge/corelib-actions.md","filePath":"modules/forge/corelib-actions.md","lastUpdated":null}'),r={name:"modules/forge/corelib-actions.md"};function o(l,e,d,h,n,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="corelib-动作" tabindex="-1">CoreLib 动作 <a class="header-anchor" href="#corelib-动作" aria-label="Permalink to &quot;CoreLib 动作&quot;">​</a></h1><p>EmakiForge 启用后会向 CoreLib 动作注册表追加锻造物品刷新段。它们用于在配置管道中重建锻造层、刷新玩家背包中的锻造物品，或在批量配置变更后刷新在线玩家物品。</p><blockquote><p>本页只记录 EmakiForge 注册的段；CoreLib 自带通用段见 <a href="./../corelib/actions.html">CoreLib 动作系统</a>。当前段 ID 只使用下表中的规范名，不再提供历史别名入口。旧的 <code>emakiforge_refresh_held</code> 现在写作 <code>forge_refresh_held</code>，另外两个同理。</p></blockquote><h2 id="段-id" tabindex="-1">段 ID <a class="header-anchor" href="#段-id" aria-label="Permalink to &quot;段 ID&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段 ID</th><th>用途</th><th>目标要求</th></tr></thead><tbody><tr><td><code>forge_refresh_held</code></td><td>刷新目标玩家主手的锻造物品。</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>forge_refresh_player</code></td><td>刷新目标玩家背包内的锻造物品。</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>forge_refresh_all</code></td><td>刷新全部在线玩家的锻造物品。</td><td><code>NONE</code></td></tr></tbody></table><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><p>这三个段不读取额外参数。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | forge_refresh_held&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | forge_refresh_player&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 不需要目标，可省略 source</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;forge_refresh_all&#39;</span></span></code></pre></div><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to &quot;使用提示&quot;">​</a></h2><ul><li><code>forge_refresh_held</code> 只处理主手物品；玩家主手为空时该段会跳过。</li><li><code>forge_refresh_player</code> 需要玩家目标，会调用 EmakiForge 刷新服务处理该玩家背包。</li><li><code>forge_refresh_all</code> 目标要求是 <code>NONE</code>，可以单独成为一条管道，适合管理员管道模板或配置变更后的批量刷新。它会等待异步刷新完成，最长等待 20 秒；超时、部分失败，或刷新期间配置世代发生变化，都会以失败结束。</li></ul>`,11)])])}const k=a(r,[["render",o]]);export{_ as __pageData,k as default};
